const dynamicTranslationRules = [
  [/^暂时无法同步：(.*) 请刷新重试。$/, "暂时无法同步：{message} 请刷新重试。", match => ({ message: t(match[1]) })],
  [/^会话恢复失败：(.*)$/, "会话恢复失败：{message}", match => ({ message: t(match[1]) })],
  [/^检查完成，归档 (\d+) 条记忆$/, "检查完成，归档 {count} 条记忆", match => ({ count: match[1] })],
  [/^来源会话不可用：(.*)$/, "来源会话不可用：{message}", match => ({ message: t(match[1]) })],
  [/^设置未保存：(.*)$/, "设置未保存：{message}", match => ({ message: t(match[1]) })],
];
function interpolate(value, params) {
  for (const [key, replacement] of Object.entries(params || {})) value = value.replaceAll(`{${key}}`, String(replacement));
  return value;
}
export function t(text, params) {
  if (typeof text !== "string") return text ?? "";
  if (language.value === "zh") return interpolate(text, params);
  const translated = translations[text];
  if (translated) return interpolate(translated, params);
  for (const [pattern, key, paramsFor] of dynamicTranslationRules) {
    const match = text.match(pattern);
    if (match) return t(key, paramsFor(match));
  }
  return interpolate(text, params);
}
export function setLanguage(value){language.value=value;document.documentElement.lang=value === "zh" ? "zh-CN" : "en";try{localStorage.setItem("cm.language",value);}catch{}}
setLanguage(language.value);

